    internal class AcceptedContextConverter : JsonConverter<AcceptedContext>
    {
        public override bool CanConvert(Type t) => t == typeof(AcceptedContext);

        public override AcceptedContext Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
        {
            var value = reader.GetString();
            switch (value)
            {
                case "artifact-reference":
                    return AcceptedContext.ArtifactReference;
                case "inline-text":
                    return AcceptedContext.InlineText;
                case "uri-reference":
                    return AcceptedContext.UriReference;
            }
            throw new Exception("Cannot unmarshal type AcceptedContext");
        }

        public override void Write(Utf8JsonWriter writer, AcceptedContext value, JsonSerializerOptions options)
        {
            switch (value)
            {
                case AcceptedContext.ArtifactReference:
                    JsonSerializer.Serialize(writer, "artifact-reference", options);
                    return;
                case AcceptedContext.InlineText:
                    JsonSerializer.Serialize(writer, "inline-text", options);
                    return;
                case AcceptedContext.UriReference:
                    JsonSerializer.Serialize(writer, "uri-reference", options);
                    return;
            }
            throw new Exception("Cannot marshal type AcceptedContext");
        }

        public static readonly AcceptedContextConverter Singleton = new AcceptedContextConverter();
    }

